import type { ComponentProps, ReactNode } from 'react'
import { cn } from '@/lib/utils'
import styles from './Badge.module.css'

export interface BadgeProps extends Omit<ComponentProps<'span'>, 'children'> {
  count?: number
  variant?: 'primary' | 'accent' | 'secondary' | 'destructive' | 'success' | 'warning'
  /**
   * Size of a dot: 8px (`md`) or 6px (`sm`). A count is 16px tall at either.
   * `sm` on a count is deprecated: it renders the `md` badge. In the next
   * release `sm` is for dots only.
   */
  size?: 'sm' | 'md'
  /** A dot with no number: "something new", not "how many". */
  isDot?: boolean
  /** Counts above this show as `maxCount+`. */
  maxCount?: number
  /** Pins the badge to a corner of `children` instead of sitting inline. */
  isFloating?: boolean
  floatingPlacement?: 'top-start' | 'top-end' | 'bottom-start' | 'bottom-end'
  /** The element a floating badge is pinned to. */
  children?: ReactNode
}

let hasWarned = false

export function Badge({
  count,
  variant = 'primary',
  size = 'md',
  isDot = false,
  maxCount,
  isFloating = false,
  floatingPlacement = 'top-end',
  children,
  className,
  ...props
}: BadgeProps) {
  const hasBadge = isDot || count !== undefined
  if (import.meta.env.DEV && !hasWarned && size === 'sm' && hasBadge && !isDot) {
    hasWarned = true
    console.warn('Badge: `size="sm"` on a count is deprecated and renders as `md`. Keep it for dots only.')
  }
  const badge = hasBadge && (
    <span
      // A labelled badge is an image of a state: a plain span may not carry
      // aria-label. An unlabelled dot says nothing, and a floating badge sits
      // outside the element it describes, so both are hidden — the meaning
      // belongs in the anchor's own name.
      role={props['aria-label'] ? 'img' : undefined}
      aria-hidden={!props['aria-label'] && (isDot || isFloating) ? true : undefined}
      className={cn(
        styles.badge,
        styles[variant],
        styles[size],
        isDot && styles.dot,
        isFloating && [styles.floating, styles[floatingPlacement]],
        className,
      )}
      {...props}
    >
      {isDot ? null : maxCount !== undefined && count! > maxCount ? `${maxCount}+` : count}
    </span>
  )

  if (children === undefined) return badge
  return (
    <span className={styles.anchor}>
      {children}
      {badge}
    </span>
  )
}

.anchor {
  position: relative;
  display: inline-flex;
  align-items: center;
  gap: var(--space-2);
}

/* One count badge, Atlassian's: 16px tall, at least 24px wide, 4px either
   side, 12/16 text and a 2px corner. The step, not a control radius: it
   follows the preset's factor and never becomes a pill. */
.badge {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  box-sizing: border-box;
  block-size: var(--badge-md);
  min-inline-size: var(--box-sm);
  padding-inline: var(--space-1);
  border-radius: var(--radius-xs);
  font-family: var(--font-sans);
  font-size: var(--text-body-sm);
  line-height: var(--leading-body-sm);
  font-weight: 500;
  font-variant-numeric: tabular-nums;
  white-space: nowrap;
}

/* A dot stays round, and keeps its two sizes: 8px, or 6px at sm. */
.dot {
  min-inline-size: 0;
  padding: 0;
  inline-size: var(--badge-dot-md);
  block-size: var(--badge-dot-md);
  border-radius: var(--radius-pill);
}

.dot.sm {
  inline-size: var(--badge-dot-sm);
  block-size: var(--badge-dot-sm);
}

.primary {
  background: var(--color-background-brand-bold);
  color: var(--color-text-brand-inverse);
}

/* The token set has one brand hue, so accent is the inverted neutral: the
   strongest contrast available without inventing a colour. */
.accent {
  background: var(--color-text);
  color: var(--color-surface);
}

.secondary {
  background: var(--color-background-neutral);
  color: var(--color-text);
}

/* A dot has no text to carry it, so it must reach 3:1 against the page on
   its own; the secondary fill is far below that. */
.dot.secondary {
  background: var(--color-text-subtlest);
}

.destructive {
  background: var(--color-background-danger-bold);
  color: var(--color-text-danger-inverse);
}

/* Status colours, for presence and state dots: success is Online, warning
   Away or Pending. Offline is secondary; info would repeat primary's blue. */
.success {
  background: var(--color-background-success-bold);
  color: var(--color-text-success-inverse);
}

.warning {
  background: var(--color-background-warning-bold);
  color: var(--color-text-warning-inverse);
}

/* Same 3:1 rule as the secondary dot: amber-500 reaches only 2:1 on the
   light page, so the dot steps down to amber-600. */
.dot.warning {
  background: var(--color-icon-warning);
}

/* The ring in the page background separates the badge from whatever it
   overlaps, so it reads on top of an icon or avatar of any colour. 2px is
   the same width as the focus ring: enough to read as a gap, not a border. */
.floating {
  position: absolute;
  box-shadow: 0 0 0 2px var(--color-surface);
}

/* start/end are physical left/right, so RTL pages get mirrored
   placement. Add [dir='rtl'] overrides when an RTL consumer appears; not
   :dir(rtl), which the build lowers to a :lang() list (see Switch). */
.top-start {
  top: 0;
  left: 0;
  translate: -50% -50%;
}

.top-end {
  top: 0;
  right: 0;
  translate: 50% -50%;
}

.bottom-start {
  bottom: 0;
  left: 0;
  translate: -50% 50%;
}

.bottom-end {
  bottom: 0;
  right: 0;
  translate: 50% 50%;
}
